(function(){'use strict';
var CROP_KEY='welog-direct-split-crop-v1', STICKER_KEY='welog-direct-stickers-v1';
function read(k,d){try{return JSON.parse(localStorage.getItem(k))||d}catch(e){return d}}
function write(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}
var crop=read(CROP_KEY,{t:0,r:0,b:0,l:0});
function applyCrop(){var el=document.querySelector('#sheet .center .pair-split');if(!el)return;el.style.clipPath='inset('+crop.t+'% '+crop.r+'% '+crop.b+'% '+crop.l+'%)';el.dataset.directCrop='1'}
function removeOldCropPanel(){document.querySelectorAll('.welog-split-area-control').forEach(function(n){n.remove()})}
function layoutEditing(){return !!document.querySelector('.layout-editing,.is-layout-editing,[data-layout-editing="true"]')||!!document.querySelector('.layout-editor-toolbar,.layout-edit-toolbar')}
function addCropHandles(){var el=document.querySelector('#sheet .center .pair-split');if(!el||el.querySelector('.direct-crop-ui'))return;el.style.position='relative';var ui=document.createElement('div');ui.className='direct-crop-ui';ui.innerHTML='<i data-edge="t"></i><i data-edge="r"></i><i data-edge="b"></i><i data-edge="l"></i>';
el.appendChild(ui);var start=null;ui.addEventListener('pointerdown',function(e){var h=e.target.closest('[data-edge]');if(!h)return;e.preventDefault();e.stopPropagation();var rect=el.getBoundingClientRect();start={edge:h.dataset.edge,x:e.clientX,y:e.clientY,rect:rect,base:Object.assign({},crop)};h.setPointerCapture&&h.setPointerCapture(e.pointerId)});ui.addEventListener('pointermove',function(e){if(!start)return;var dx=(e.clientX-start.x)/start.rect.width*100,dy=(e.clientY-start.y)/start.rect.height*100;crop=Object.assign({},start.base);if(start.edge==='l')crop.l=Math.max(0,Math.min(45,start.base.l+dx));if(start.edge==='r')crop.r=Math.max(0,Math.min(45,start.base.r-dx));if(start.edge==='t')crop.t=Math.max(0,Math.min(45,start.base.t+dy));if(start.edge==='b')crop.b=Math.max(0,Math.min(45,start.base.b-dy));applyCrop()});ui.addEventListener('pointerup',function(){if(start){write(CROP_KEY,crop);start=null}})}
function syncCropUI(){removeOldCropPanel();applyCrop();var el=document.querySelector('#sheet .center .pair-split');if(!el)return;if(layoutEditing())addCropHandles();else{var u=el.querySelector('.direct-crop-ui');if(u)u.remove()}}
function stickerLayer(){var sheet=document.getElementById('sheet');if(!sheet)return null;var l=sheet.querySelector('.direct-sticker-layer');if(!l){l=document.createElement('div');l.className='direct-sticker-layer';sheet.appendChild(l)}return l}
function getStickers(){return read(STICKER_KEY,[])} function saveStickers(v){write(STICKER_KEY,v)}
function renderStickers(){var layer=stickerLayer();if(!layer)return;var arr=getStickers();layer.innerHTML='';arr.forEach(function(s,i){var w=document.createElement('div');w.className='direct-sticker';w.dataset.i=i;w.style.left=s.x+'%';w.style.top=s.y+'%';w.style.width=s.w+'px';w.style.transform='translate(-50%,-50%) rotate('+(s.rot||0)+'deg)';w.innerHTML='<img draggable="false"><button type="button" class="st-del">×</button><i class="st-resize"></i><i class="st-rotate"></i>';w.querySelector('img').src=s.src;layer.appendChild(w)});bindStickerGestures(layer)}
function bindStickerGestures(layer){layer.querySelectorAll('.direct-sticker').forEach(function(w){var i=+w.dataset.i,mode='',sx=0,sy=0,base=null;w.addEventListener('pointerdown',function(e){if(e.target.closest('.st-del'))return;var arr=getStickers();base=Object.assign({},arr[i]);sx=e.clientX;sy=e.clientY;mode=e.target.closest('.st-resize')?'resize':e.target.closest('.st-rotate')?'rotate':'move';e.preventDefault();e.stopPropagation();w.setPointerCapture&&w.setPointerCapture(e.pointerId)});w.addEventListener('pointermove',function(e){if(!mode)return;var arr=getStickers(),sheet=document.getElementById('sheet').getBoundingClientRect(),dx=e.clientX-sx,dy=e.clientY-sy;if(mode==='move'){arr[i].x=Math.max(0,Math.min(100,base.x+dx/sheet.width*100));arr[i].y=Math.max(0,Math.min(100,base.y+dy/sheet.height*100))}else if(mode==='resize'){arr[i].w=Math.max(20,Math.min(600,base.w+dx))}else{var r=w.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;arr[i].rot=Math.atan2(e.clientY-cy,e.clientX-cx)*180/Math.PI}saveStickers(arr);renderStickers()});w.addEventListener('pointerup',function(){mode=''});w.querySelector('.st-del').addEventListener('click',function(e){e.stopPropagation();var arr=getStickers();arr.splice(i,1);saveStickers(arr);renderStickers()})})}
function hookStickerUploads(){document.addEventListener('change',function(e){var inp=e.target;if(!inp.matches('[data-sticker-upload]')||!inp.files||!inp.files[0])return;var f=inp.files[0],r=new FileReader();r.onload=function(){var arr=getStickers();arr.push({src:r.result,x:50,y:50,w:120,rot:0});saveStickers(arr);renderStickers();inp.value=''};r.readAsDataURL(f)},true);document.addEventListener('click',function(e){var b=e.target.closest('[data-sticker-add]');if(!b)return;setTimeout(function(){var imgs=document.querySelectorAll('.sticker-gallery img');var img=imgs[+b.dataset.stickerAdd];if(!img)return;var arr=getStickers();arr.push({src:img.src,x:50,y:50,w:120,rot:0});saveStickers(arr);renderStickers()},0)},true)}
var mo=new MutationObserver(function(){syncCropUI();renderStickers()});function boot(){var s=document.getElementById('sheet');if(!s)return;mo.observe(s,{childList:true,subtree:true});hookStickerUploads();syncCropUI();renderStickers();document.addEventListener('click',function(){setTimeout(syncCropUI,40)},true)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();